                    [0x745524d8e00450beUL] = "¡Vamos, sacos de carne! ¡Es la hora del espectáculo!",
                    [0x759cb1960641dd4bUL] = "¿Cuerpos?",
                    [0x76590b86f59c73cbUL] = "¡Bien, listillo, esta es tu última advertencia! Voy a contar hasta diez, ¡y más vale que te largues antes de que termine!",
                    [0x7cb05c036d2c4aa9UL] = "¡Uno!",
