                    [0xeee6f11d36af4eccUL] = "Não queres acabar como estes pobres coitados. Parece que lhes deu medo de palco, he he!",
                    [0xef6bff69b221b98dUL] = "O que fariam as pessoas, pergunto-me, sem o seu precioso entretenimento?",
                    [0xefe036c18f965932UL] = "É tudo, pessoal! MAS não se esqueçam de sintonizar amanhã — é quando a luta A SÉRIO começa.",
